body.script:
(() => {
    const configId = ;
    const token = "";
    const statusEl = document.getElementById("status");
    const video = document.getElementById("video");
    const manualInput = document.getElementById("manual-input");
    const sendManualBtn = document.getElementById("send-manual");
    const toggleCameraBtn = document.getElementById("toggle-camera");
    let cameraStream = null;
    let detector = null;
    let scanTimer = null;
    let zxingReader = null;
    let zxingControls = null;
    let scannerMode = null;

    const setStatus = (text) => {
        statusEl.textContent = text;
    };

    const getReadableCameraError = (err) => {
        const name = err?.name || "UnknownError";
        const message = err?.message || "";
        const base = `Camera error: ${name}${message ? ` - ${message}` : ""}.`;
        if (name === "NotAllowedError") {
            return `${base} Hay cap quyen Camera cho website trong Safari (aA > Website Settings > Camera > Allow).`;
        }
        if (name === "NotFoundError") {
            return `${base} Khong tim thay camera tren thiet bi.`;
        }
        if (name === "NotReadableError") {
            return `${base} Camera dang duoc app khac su dung. Hay dong app camera/scan khac roi thu lai.`;
        }
        if (name === "NotSupportedError") {
            return `${base} Trinh duyet/webview hien tai khong ho tro API camera. Hay mo bang Safari truc tiep.`;
        }
        if (name === "SecurityError") {
            return `${base} Trinh duyet chan camera do context khong an toan. Thu mo lai bang Safari truc tiep.`;
        }
        return `${base} Neu dang mo tu Zalo/Messenger, hay mo link scanner bang Safari truc tiep.`;
    };

    const pushBarcode = async (barcode) => {
        const code = (barcode || "").trim();
        if (!code) {
            return;
        }
        try {
            const response = await fetch("/pos/mobile_scanner/push", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {
                        config_id: configId,
                        token: token,
                        barcode: code,
                    },
                    id: Date.now(),
                }),
            });
            const payload = await response.json();
            if (payload.result && payload.result.ok) {
                setStatus(`Da gui: ${code}`);
            } else {
                setStatus("Gui that bai, vui long thu lai.");
            }
        } catch (err) {
            setStatus("Loi ket noi Odoo.");
        }
    };

    const stopCamera = () => {
        if (zxingControls) {
            zxingControls.stop();
            zxingControls = null;
        }
        if (zxingReader) {
            zxingReader.reset();
            zxingReader = null;
        }
        if (scanTimer) {
            clearInterval(scanTimer);
            scanTimer = null;
        }
        if (cameraStream) {
            cameraStream.getTracks().forEach((track) => track.stop());
            cameraStream = null;
        }
        video.srcObject = null;
        scannerMode = null;
    };

    const startZXingScanner = async () => {
        if (!window.ZXing || !window.ZXing.BrowserMultiFormatReader) {
            setStatus("Khong tai duoc thu vien quet ma vach. Dung nhap tay.");
            return false;
        }
        try {
            zxingReader = new window.ZXing.BrowserMultiFormatReader();
            zxingControls = await zxingReader.decodeFromVideoDevice(
                null,
                "video",
                async (result) => {
                    if (!result) {
                        return;
                    }
                    await pushBarcode(result.getText());
                }
            );
            scannerMode = "zxing";
            setStatus("Dang quet (iPhone compatible)...");
            return true;
        } catch (err) {
            setStatus(getReadableCameraError(err));
            return false;
        }
    };

    const startCamera = async () => {
        stopCamera();
        if (!("BarcodeDetector" in window)) {
            await startZXingScanner();
            return;
        }
        try {
            detector = new BarcodeDetector({
                formats: [
                    "ean_13",
                    "ean_8",
                    "upc_a",
                    "upc_e",
                    "code_128",
                    "code_39",
                    "qr_code",
                ],
            });
            cameraStream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: "environment" },
                audio: false,
            });
            video.srcObject = cameraStream;
            scannerMode = "native";
            setStatus("Dang quet... huong camera vao barcode.");
            scanTimer = setInterval(async () => {
                if (!detector || !video || video.readyState < 2) {
                    return;
                }
                try {
                    const barcodes = await detector.detect(video);
                    if (barcodes.length) {
                        const value = barcodes[0].rawValue;
                        await pushBarcode(value);
                    }
                } catch (err) {
                    // ignore frame errors
                }
            }, 900);
        } catch (err) {
            const started = await startZXingScanner();
            if (!started) {
                setStatus(getReadableCameraError(err));
            }
        }
    };

    sendManualBtn.addEventListener("click", async () => {
        await pushBarcode(manualInput.value);
        manualInput.value = "";
        manualInput.focus();
    });
    manualInput.addEventListener("keydown", async (event) => {
        if (event.key === "Enter") {
            await pushBarcode(manualInput.value);
            manualInput.value = "";
        }
    });
    toggleCameraBtn.addEventListener("click", async () => {
        if (cameraStream || zxingControls || scannerMode) {
            stopCamera();
            setStatus("Da tat camera.");
            toggleCameraBtn.textContent = "Bat camera";
        } else {
            await startCamera();
            toggleCameraBtn.textContent = "Tat camera";
        }
    });

    startCamera();
})();
